import { NextResponse } from 'next/server';

let customers = [
    { id: 'cust_001', name: 'Lutero E Associados', doc: '12.345.678/0001-90', email: 'contato@lutero.com.br', phone: '(11) 98877-6655', total_spent: 149.90, has_certificate: true, certificate_expiration: '2026-03-15', seller: 'Maria Silva' },
    { id: 'cust_002', name: 'Montenegro E Duarte', doc: '123.456.789-00', email: 'jorge@montenegro.com', phone: '(11) 97766-5544', total_spent: 299.00, has_certificate: true, certificate_expiration: '2027-01-29', seller: 'Maria Silva' },
    { id: 'cust_003', name: 'Fictitious Corp', doc: '99.888.777/0001-66', email: 'vendas@fictitious.com', phone: '(21) 91122-3344', total_spent: 0, has_certificate: false, seller: 'Externo B' },
];

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const seller = searchParams.get('seller');

    let filtered = customers;
    if (seller && seller !== 'admin') {
        filtered = customers.filter(c => c.seller === seller);
    }

    return NextResponse.json(filtered);
}

export async function POST(request: Request) {
    const data = await request.json();
    const newCustomer = {
        ...data,
        id: `cust_${Math.floor(Math.random() * 1000)}`,
        total_spent: 0,
        has_certificate: false
    };

    customers.push(newCustomer);
    return NextResponse.json(newCustomer, { status: 201 });
}
export async function PUT(request: Request) {
    const data = await request.json();
    const { id, ...updates } = data;

    const index = customers.findIndex(c => c.id === id);
    if (index === -1) {
        return NextResponse.json({ error: "Customer not found" }, { status: 404 });
    }

    customers[index] = { ...customers[index], ...updates };
    return NextResponse.json(customers[index]);
}

export async function DELETE(request: Request) {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    const index = customers.findIndex(c => c.id === id);
    if (index === -1) {
        return NextResponse.json({ error: "Customer not found" }, { status: 404 });
    }

    const deleted = customers.splice(index, 1);
    return NextResponse.json(deleted[0]);
}
